Migrate the products list page from Pages Router to App Router. This is the most complex page due to modal routing.

**Current Implementation (pages/products.js):**
```js
import React, { useState } from 'react'
import Router, { withRouter } from 'next/router'
import Link from 'next/link'
// ... components

const useProductRouteModal = router => {
  const [isModalOpen, setModalState] = useState(false)
  const [prevPathname, setPrevPathname] = useState(router.asPath)
  const closeModal = () => {
    setModalState(false)
    Router.replace(prevPathname)
  }
  const openModal = (e, product) => {
    e.preventDefault()
    setPrevPathname(router.asPath)
    setModalState(true)
    Router.push(\`${router.asPath}&pid=${product.id}\`, \`/product?id=${product.id}\`, {
      shallow: true
    })
  }
  return [isModalOpen, openModal, closeModal]
}

const ProductList = ({ router }) => {
  const [isProductModalOpen, openProductModal, closeProductModal] = useProductRouteModal(router)
  // Uses router.query.cgid, router.query.pid
  return (
    <Layout>
      <CategoryHeader />
      <CategoryHero />
      <CategoryProductList onProductClick={openProductModal} />
      <ProductDetailModal
        selectedProductId={router.query.pid}
        isOpen={isProductModalOpen}
        close={closeProductModal}
      />
    </Layout>
  )
}

export default withRouter(ProductList)
```

**Migration Challenges:**
1. withRouter HOC -> useRouter, useSearchParams, usePathname from next/navigation
2. Complex shallow routing for modal
3. Router.push/replace with as parameter (URL masking)

**Target Implementation:**

**app/products/page.js (Server Component):**
```js
import ProductsContent from './products-content'

export const metadata = {
  title: 'Products - ecomm-next',
}

export default function ProductsPage() {
  return <ProductsContent />
}
```

**app/products/products-content.js (Client Component):**
```js
'use client'
import { useState } from 'react'
import { useRouter, useSearchParams, usePathname } from 'next/navigation'
import Layout from '../../components/Layout'
import CategoryHeader from '../../components/CategoryHeader'
import CategoryHero from '../../components/CategoryHero'
import CategoryProductList from '../../components/CategoryProductList'
import ProductDetailModal from '../../components/ProductDetailModal'

function useProductRouteModal() {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()

  const [isModalOpen, setModalState] = useState(false)
  const [prevPath, setPrevPath] = useState('')

  const closeModal = () => {
    setModalState(false)
    router.replace(prevPath)
  }

  const openModal = (e, product) => {
    e.preventDefault()
    setPrevPath(pathname + '?' + searchParams.toString())
    setModalState(true)

    // Create new search params
    const newParams = new URLSearchParams(searchParams)
    newParams.set('pid', product.id)
    router.push(pathname + '?' + newParams.toString())
  }

  return [isModalOpen, openModal, closeModal]
}

export default function ProductsContent() {
  const [isModalOpen, openModal, closeModal] = useProductRouteModal()
  const searchParams = useSearchParams()
  const pid = searchParams.get('pid')

  return (
    <Layout>
      <CategoryHeader />
      <CategoryHero />
      <CategoryProductList onProductClick={openModal} />
      <ProductDetailModal
        selectedProductId={pid}
        isOpen={isModalOpen}
        close={closeModal}
      />
    </Layout>
  )
}
```

**App Router Changes for Modal Routing:**
- router.asPath is gone -> use usePathname() + useSearchParams()
- Router.push/replace -> router.push/replace (from useRouter)
- shallow: true option removed (App Router handles differently)
- URL masking (as parameter) not directly supported - may need workaround

**Alternative: Parallel Routes (advanced)**
App Router supports parallel routes with @modal slot for intercepting routes. Consider for future enhancement.

**Files Created:**
- app/products/page.js
- app/products/products-content.js

**Files to Eventually Remove:**
- pages/products.js

**Acceptance Criteria:**
- [ ] Products page renders at /products
- [ ] Product modal opens on click
- [ ] URL updates with pid parameter
- [ ] Modal closes and returns to list
- [ ] CategoryHeader, CategoryHero, CategoryProductList work

